--
-- Table structure for table `neu_miniapp_cli_key`
--

DROP TABLE IF EXISTS `neu_miniapp_cli_key`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `neu_miniapp_cli_key` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `app_id` varchar(64) NOT NULL COMMENT '小程序 ID',
  `secret_cipher` varchar(512) NOT NULL COMMENT '加密后的 secret，不保存明文',
  `secret_digest` varchar(128) NOT NULL COMMENT 'secret 的 HMAC-SHA256 摘要，用于审计去重和泄露排查',
  `secret_last4` varchar(8) NOT NULL COMMENT 'secret 后 4 位，用于页面识别',
  `name` varchar(128) NOT NULL COMMENT '密钥名称',
  `creator_uid` bigint DEFAULT NULL COMMENT '密钥创建版本或发起提审的用户 UID',
  `ip_whitelist_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否启用 IP 白名单，0 否，1 是',
  `ip_whitelist` text COMMENT 'IPv4/CIDR 白名单列表，JSON 格式',
  `last_used_time` bigint DEFAULT NULL COMMENT '最近使用时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0 active, 1 disabled, 2 expired',
  `expire_time` bigint DEFAULT NULL COMMENT '过期时间',
  `disable_reason` varchar(255) DEFAULT NULL COMMENT '禁用原因',
  `last_reset_time` bigint DEFAULT NULL COMMENT '最近一次重置时间',
  `ctime` bigint NOT NULL COMMENT '创建时间',
  `mtime` bigint NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_app_id_status` (`app_id`,`status`),
  KEY `idx_app_id_ctime` (`app_id`,`ctime`)
) ENGINE=InnoDB AUTO_INCREMENT=2114601000102641667 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='小程序 CLI 密钥表';
/*!40101 SET character_set_client = @saved_cs_client */;

