CREATE TABLE `neu_miniapp_domain_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) NOT NULL COMMENT '小程序 ID',
  `domain_type` tinyint NOT NULL COMMENT '1 request, 2 web-view',
  `domain_host` varchar(255) NOT NULL COMMENT '规范化后的域名 host',
  `sort_no` int NOT NULL DEFAULT '0' COMMENT '同类型域名展示顺序',
  `dns_check_status` tinyint NOT NULL DEFAULT '0' COMMENT 'DNS 校验状态，0 unknown',
  `https_check_status` tinyint NOT NULL DEFAULT '0' COMMENT 'HTTPS 校验状态，0 unknown',
  `last_check_time` bigint DEFAULT NULL COMMENT '最近一次校验时间',
  `check_message` varchar(255) DEFAULT NULL COMMENT '最近一次校验结果说明',
  `ctime` bigint NOT NULL COMMENT '创建时间',
  `mtime` bigint NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_domain_type_host` (`app_id`,`domain_type`,`domain_host`),
  KEY `idx_app_domain_type_sort` (`app_id`,`domain_type`,`sort_no`)
